/**
 * Unit tests for {@link ProcessorTemplateHandler#handleOpenElement(IOpenElementTag)}.
 *
 * <p>These tests drive the handler directly (it is a pure event handler) and assert on the
 * events that reach the rest of the handler chain, as well as on the interactions with the
 * engine context and the temporary gathering/model state.</p>
 */
class ProcessorTemplateHandlerHandleOpenElementTests {


    private IEngineConfiguration configuration;
    private IEngineContext context;
    private RecordingTemplateHandler next;
    private ProcessorTemplateHandler handler;


    @BeforeEach
    void setUp() {

        this.configuration = mock(IEngineConfiguration.class);
        when(this.configuration.getElementDefinitions()).thenReturn(new ElementDefinitions(Collections.emptyMap()));
        when(this.configuration.getAttributeDefinitions()).thenReturn(new AttributeDefinitions(Collections.emptyMap()));
        when(this.configuration.getTemplateBoundariesProcessors(any(TemplateMode.class))).thenReturn(Collections.<ITemplateBoundariesProcessor>emptySet());
        when(this.configuration.getCDATASectionProcessors(any(TemplateMode.class))).thenReturn(Collections.<ICDATASectionProcessor>emptySet());
        when(this.configuration.getCommentProcessors(any(TemplateMode.class))).thenReturn(Collections.<ICommentProcessor>emptySet());
        when(this.configuration.getDocTypeProcessors(any(TemplateMode.class))).thenReturn(Collections.<IDocTypeProcessor>emptySet());
        when(this.configuration.getProcessingInstructionProcessors(any(TemplateMode.class))).thenReturn(Collections.<IProcessingInstructionProcessor>emptySet());
        when(this.configuration.getTextProcessors(any(TemplateMode.class))).thenReturn(Collections.<ITextProcessor>emptySet());
        when(this.configuration.getXMLDeclarationProcessors(any(TemplateMode.class))).thenReturn(Collections.<IXMLDeclarationProcessor>emptySet());

        this.context = mock(IEngineContext.class);
        when(this.context.getTemplateMode()).thenReturn(TemplateMode.HTML);
        when(this.context.getConfiguration()).thenReturn(this.configuration);

        this.next = new RecordingTemplateHandler();
        this.handler = new ProcessorTemplateHandler();
        this.handler.setNext(this.next);
        this.handler.setContext(this.context);

        // Only interactions produced by handleOpenElement should be inspected by the tests.
        clearInvocations(this.context);

    }


    // ------------------------------------------------------------------------------------------
    // FAIL-FAST AND BASIC DELEGATION
    // ------------------------------------------------------------------------------------------

    @Test
    void openElementWithoutAssociatedProcessorsIsDelegatedToNext() {

        final OpenElementTag tag = openTag("div");

        this.handler.handleOpenElement(tag);

        assertEquals(Collections.singletonList("open:div"), this.next.events);
        assertSame(tag, this.next.openElements.get(0));
        verify(this.context).increaseLevel();
        verify(this.context).setElementTag(tag);

    }


    @Test
    void openElementWithNoOpProcessorIsDelegatedAfterProcessing() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                // No instruction: the element must be delegated unchanged.
            }
        });
        final OpenElementTag tag = openTag("div", processor);

        this.handler.handleOpenElement(tag);

        assertEquals(Collections.singletonList("open:div"), this.next.events);
        assertSame(tag, this.next.openElements.get(0));
        assertEquals(1, processor.executions);

    }


    // ------------------------------------------------------------------------------------------
    // THROTTLING
    // ------------------------------------------------------------------------------------------

    @Test
    void stoppedThrottlingQueuesTheEventWithoutProcessingIt() {

        final TemplateFlowController flowController = new TemplateFlowController();
        flowController.stopProcessing = true;
        this.handler.setFlowController(flowController);

        final OpenElementTag first = openTag("div");
        final OpenElementTag second = openTag("span");

        this.handler.handleOpenElement(first);
        this.handler.handleOpenElement(second);

        assertTrue(this.next.events.isEmpty());
        assertTrue(flowController.processorTemplateHandlerPending);
        verify(this.context, never()).increaseLevel();
        verify(this.context, never()).setElementTag(any(IProcessableElementTag.class));

    }


    @Test
    void throttlingWithQueuedModelProcessesTheModelBeforeReturning() {

        final TemplateFlowController flowController = new TemplateFlowController();
        this.handler.setFlowController(flowController);

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.setBody("THROTTLED", false);
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Arrays.asList("open:div", "text:THROTTLED"), this.next.events);
        assertFalse(flowController.processorTemplateHandlerPending);

    }


    // ------------------------------------------------------------------------------------------
    // IElementTagProcessor RESULT HANDLING
    // ------------------------------------------------------------------------------------------

    @Test
    void setBodyTextEmitsTheTextAfterDelegatingAndSkipsTheRealBody() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.setBody("BODY-TEXT", false);
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Arrays.asList("open:div", "text:BODY-TEXT"), this.next.events);

        // Body must now be skipped: a child element cannot reach the next handler.
        this.handler.handleOpenElement(openTag("span"));
        assertEquals(Arrays.asList("open:div", "text:BODY-TEXT"), this.next.events);

    }


    @Test
    void setBodyModelEmitsTheModelAfterDelegating() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.setBody(modelWithText("BODY-MODEL"), false);
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Arrays.asList("open:div", "text:BODY-MODEL"), this.next.events);

    }


    @Test
    void insertBeforeEmitsTheModelBeforeDelegatingTheElement() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.insertBefore(modelWithText("BEFORE"));
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Arrays.asList("text:BEFORE", "open:div"), this.next.events);

    }


    @Test
    void insertImmediatelyAfterEmitsTheModelAfterDelegatingTheElement() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.insertImmediatelyAfter(modelWithText("AFTER"), false);
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Arrays.asList("open:div", "text:AFTER"), this.next.events);

    }


    @Test
    void replaceWithTextDiscardsTheElementAndEmitsOnlyTheReplacementText() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.replaceWith("REPLACED-TEXT", false);
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Collections.singletonList("text:REPLACED-TEXT"), this.next.events);

        // The complete element (body included) was replaced, so a child is not processed either.
        this.handler.handleOpenElement(openTag("span"));
        assertEquals(Collections.singletonList("text:REPLACED-TEXT"), this.next.events);

    }


    @Test
    void replaceWithModelDiscardsTheElementAndEmitsOnlyTheReplacementModel() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.replaceWith(modelWithText("REPLACED-MODEL"), false);
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Collections.singletonList("text:REPLACED-MODEL"), this.next.events);

    }


    @Test
    void removeElementDiscardsTheElementAndItsCompleteBody() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.removeElement();
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertTrue(this.next.events.isEmpty());

        // The complete element was removed, so a child element is not processed.
        this.handler.handleOpenElement(openTag("span"));
        assertTrue(this.next.events.isEmpty());

    }


    @Test
    void removeTagsDiscardsTheTagButKeepsProcessingItsBody() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.removeTags();
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertTrue(this.next.events.isEmpty());

        // Only the tag is removed: children must still be processed.
        this.handler.handleOpenElement(openTag("span"));
        assertEquals(Collections.singletonList("open:span"), this.next.events);

    }


    @Test
    void removeBodyDelegatesTheTagButSkipsItsBody() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.removeBody();
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Collections.singletonList("open:div"), this.next.events);

        this.handler.handleOpenElement(openTag("span"));
        assertEquals(Collections.singletonList("open:div"), this.next.events);

    }


    @Test
    void removeAllButFirstChildDelegatesTheTagAndAllowsTheFirstChild() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.removeAllButFirstChild();
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Collections.singletonList("open:div"), this.next.events);

        // The first child element must still be processed.
        this.handler.handleOpenElement(openTag("span"));
        assertEquals(Arrays.asList("open:div", "open:span"), this.next.events);

    }


    @Test
    void localVariablesAreAppliedToTheEngineContext() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.setLocalVariable("myVar", Integer.valueOf(42));
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Collections.singletonList("open:div"), this.next.events);
        verify(this.context).setVariables(Collections.<String, Object>singletonMap("myVar", Integer.valueOf(42)));

    }


    @Test
    void tagAttributeModificationsAreAppliedBeforeDelegating() {

        final ActionTagProcessor processor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.setAttribute("data-test", "value");
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertEquals(Collections.singletonList("open:div"), this.next.events);
        assertTrue(this.next.openElements.get(0).hasAttribute("data-test"));

    }


    // ------------------------------------------------------------------------------------------
    // PROCESSING ERRORS
    // ------------------------------------------------------------------------------------------

    @Test
    void unsupportedProcessorTypeRaisesIllegalStateException() {

        final OpenElementTag tag = openTag("div", new UnsupportedElementProcessor());

        final IllegalStateException exception =
                assertThrows(IllegalStateException.class, new org.junit.jupiter.api.function.Executable() {
                    public void execute() {
                        handler.handleOpenElement(tag);
                    }
                });

        assertTrue(exception.getMessage().contains("neither a Tag Element Processor nor a Model Element Processor"));
        assertTrue(this.next.events.isEmpty());

    }


    @Test
    void modelProcessorAfterABodyModificationRaisesTemplateProcessingException() {

        final ActionTagProcessor bodyProcessor = new ActionTagProcessor(10, new Consumer<IElementTagStructureHandler>() {
            public void accept(final IElementTagStructureHandler structureHandler) {
                structureHandler.setBody("ALREADY-MODIFIED", false);
            }
        });
        final ActionModelProcessor modelProcessor = new ActionModelProcessor(20, new Consumer<IModel>() {
            public void accept(final IModel model) {
                // No-op
            }
        });
        final OpenElementTag tag = openTag("div", bodyProcessor, modelProcessor);

        final TemplateProcessingException exception =
                assertThrows(TemplateProcessingException.class, new org.junit.jupiter.api.function.Executable() {
                    public void execute() {
                        handler.handleOpenElement(tag);
                    }
                });

        assertTrue(exception.getMessage().contains("Cannot execute model processor"));
        assertTrue(this.next.events.isEmpty());

    }


    // ------------------------------------------------------------------------------------------
    // IElementModelProcessor: GATHERING
    // ------------------------------------------------------------------------------------------

    @Test
    void modelProcessorFirstExecutionStartsGatheringAndDoesNotDelegateYet() {

        final ActionModelProcessor processor = new ActionModelProcessor(10, new Consumer<IModel>() {
            public void accept(final IModel model) {
                // No-op
            }
        });

        this.handler.handleOpenElement(openTag("div", processor));

        assertTrue(this.next.events.isEmpty());

        // The controller is now gathering the element's model, so subsequent events are gathered too.
        this.handler.handleOpenElement(openTag("span"));
        assertTrue(this.next.events.isEmpty());

    }


    @Test
    void resumedModelProcessorWithNoModelChangeDelegatesTheElement() {

        final ActionModelProcessor processor = new ActionModelProcessor(10, new Consumer<IModel>() {
            public void accept(final IModel model) {
                // No-op
            }
        });
        final OpenElementTag tag = openTag("div", processor);

        final IGatheringModelProcessable gatheringModel = gatheringModelFor(processor, tag, modelWithText("GATHERED"));
        this.handler.setCurrentGatheringModel(gatheringModel);

        this.handler.handleOpenElement(tag);

        assertEquals(Collections.singletonList("open:div"), this.next.events);
        verify(this.context).setElementTag(isNull());
        verify(gatheringModel).resetGatheredSkipFlags();

    }


    @Test
    void resumedModelProcessorWithChangedModelReplacesTheElementModel() {

        final ActionModelProcessor processor = new ActionModelProcessor(10, new Consumer<IModel>() {
            public void accept(final IModel model) {
                model.add(new Text("PROCESSED"));
            }
        });
        final OpenElementTag tag = openTag("div", processor);

        final IGatheringModelProcessable gatheringModel = gatheringModelFor(processor, tag, modelWithText("GATHERED"));
        this.handler.setCurrentGatheringModel(gatheringModel);

        this.handler.handleOpenElement(tag);

        // The gathered model plus the change made by the processor must be the only output.
        assertEquals(Arrays.asList("text:GATHERED", "text:PROCESSED"), this.next.events);
        verify(this.context).setElementTag(isNull());

    }


    // ------------------------------------------------------------------------------------------
    // HELPERS
    // ------------------------------------------------------------------------------------------

    private OpenElementTag openTag(final String name, final IElementProcessor... processors) {

        final Set<IElementProcessor> processorSet =
                new LinkedHashSet<IElementProcessor>(Arrays.asList(processors));
        final HTMLElementName elementName = ElementNames.forHTMLName(name);
        final HTMLElementDefinition elementDefinition =
                new HTMLElementDefinition(elementName, HTMLElementType.NORMAL, processorSet);
        return new OpenElementTag(TemplateMode.HTML, elementDefinition, name, null, false, "test-template", 1, 1);

    }


    private Model modelWithText(final String text) {
        final Model model = new Model(this.configuration, TemplateMode.HTML);
        model.add(new Text(text));
        return model;
    }


    private IGatheringModelProcessable gatheringModelFor(
            final IElementModelProcessor processor, final OpenElementTag tag, final Model gatheredModel) {

        // Reproduce the iterator state existing when the model gathering finishes: the very same
        // model processor has to be returned once again, with "lastWasRepeated" == true.
        final ProcessorExecutionVars vars = new ProcessorExecutionVars();
        assertSame(processor, vars.processorIterator.next(tag));
        vars.processorIterator.setLastToBeRepeated(tag);

        final IGatheringModelProcessable gatheringModel = mock(IGatheringModelProcessable.class);
        when(gatheringModel.initializeProcessorExecutionVars()).thenReturn(vars);
        when(gatheringModel.getInnerModel()).thenReturn(gatheredModel);
        return gatheringModel;

    }


    private static final class ActionTagProcessor extends AbstractElementTagProcessor {

        private final Consumer<IElementTagStructureHandler> action;
        private int executions = 0;

        private ActionTagProcessor(final int precedence, final Consumer<IElementTagStructureHandler> action) {
            super(TemplateMode.HTML, null, null, false, null, false, precedence);
            this.action = action;
        }

        @Override
        protected void doProcess(
                final ITemplateContext context,
                final IProcessableElementTag tag,
                final IElementTagStructureHandler structureHandler) {
            this.executions++;
            this.action.accept(structureHandler);
        }

    }


    private static final class ActionModelProcessor extends AbstractElementModelProcessor {

        private final Consumer<IModel> action;

        private ActionModelProcessor(final int precedence, final Consumer<IModel> action) {
            super(TemplateMode.HTML, null, null, false, null, false, precedence);
            this.action = action;
        }

        @Override
        protected void doProcess(
                final ITemplateContext context,
                final IModel model,
                final IElementModelStructureHandler structureHandler) {
            this.action.accept(model);
        }

    }


    private static final class UnsupportedElementProcessor implements IElementProcessor {

        public TemplateMode getTemplateMode() {
            return TemplateMode.HTML;
        }

        public int getPrecedence() {
            return 100;
        }

        public MatchingElementName getMatchingElementName() {
            return null;
        }

        public MatchingAttributeName getMatchingAttributeName() {
            return null;
        }

    }


    private static final class RecordingTemplateHandler implements ITemplateHandler {

        private final List<String> events = new ArrayList<String>();
        private final List<IOpenElementTag> openElements = new ArrayList<IOpenElementTag>();
        private final List<IText> texts = new ArrayList<IText>();

        public void setNext(final ITemplateHandler next) {
            // Not needed
        }

        public void setContext(final ITemplateContext context) {
            // Not needed
        }

        public void handleTemplateStart(final ITemplateStart templateStart) {
            this.events.add("templateStart");
        }

        public void handleTemplateEnd(final ITemplateEnd templateEnd) {
            this.events.add("templateEnd");
        }

        public void handleXMLDeclaration(final IXMLDeclaration xmlDeclaration) {
            this.events.add("xmlDeclaration");
        }

        public void handleDocType(final IDocType docType) {
            this.events.add("docType");
        }

        public void handleCDATASection(final ICDATASection cdataSection) {
            this.events.add("cdata");
        }

        public void handleComment(final IComment comment) {
            this.events.add("comment");
        }

        public void handleText(final IText text) {
            this.events.add("text:" + text.getText());
            this.texts.add(text);
        }

        public void handleStandaloneElement(final IStandaloneElementTag standaloneElementTag) {
            this.events.add("standalone:" + standaloneElementTag.getElementCompleteName());
        }

        public void handleOpenElement(final IOpenElementTag openElementTag) {
            this.events.add("open:" + openElementTag.getElementCompleteName());
            this.openElements.add(openElementTag);
        }

        public void handleCloseElement(final ICloseElementTag closeElementTag) {
            this.events.add("close:" + closeElementTag.getElementCompleteName());
        }

        public void handleProcessingInstruction(final IProcessingInstruction processingInstruction) {
            this.events.add("processingInstruction");
        }

    }


}
