class ProcessorTemplateHandlerHandleOpenElementTests {


    private IEngineConfiguration configuration;
    private IEngineContext context;
    private RecordingTemplateHandler next;
    private ProcessorTemplateHandler handler;


    @BeforeEach
    void setUp() {

        this.configuration = mock(IEngineConfiguration.class);
        when(this.configuration.getElementDefinitions()).thenReturn(new ElementDefinitions(Collections.emptyMap()));
        when(this.configuration.getAttributeDefinitions()).thenReturn(new AttributeDefinitions(Collections.emptyMap()));
        when(this.configuration.getTemplateBoundariesProcessors(any(TemplateMode.class))).thenReturn(Collections.<ITemplateBoundariesProcessor>emptySet());
        when(this.configuration.getCDATASectionProcessors(any(TemplateMode.class))).thenReturn(Collections.<ICDATASectionProcessor>emptySet());
        when(this.configuration.getCommentProcessors(any(TemplateMode.class))).thenReturn(Collections.<ICommentProcessor>emptySet());
        when(this.configuration.getDocTypeProcessors(any(TemplateMode.class))).thenReturn(Collections.<IDocTypeProcessor>emptySet());
        when(this.configuration.getProcessingInstructionProcessors(any(TemplateMode.class))).thenReturn(Collections.<IProcessingInstructionProcessor>emptySet());
        when(this.configuration.getTextProcessors(any(TemplateMode.class))).thenReturn(Collections.<ITextProcessor>emptySet());
        when(this.configuration.getXMLDeclarationProcessors(any(TemplateMode.class))).thenReturn(Collections.<IXMLDeclarationProcessor>emptySet());

        this.context = mock(IEngineContext.class);
        when(this.context.getTemplateMode()).thenReturn(TemplateMode.HTML);
        when(this.context.getConfiguration()).thenReturn(this.configuration);

        this.next = new RecordingTemplateHandler();
        this.handler = new ProcessorTemplateHandler();
        this.handler.setNext(this.next);
        this.handler.setContext(this.context);

        // Only interactions produced by handleOpenElement should be inspected by the tests.
        clearInvocations(this.context);

    }


